"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["45031"],{79642(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_valor_dominio.ja_desativado","status":422,"titulo":"O valor j\xe1 est\xe1 desativado"},"descricao":{"codigo":"uniplus.configuracao.fato_valor_dominio.ja_desativado","requisitos":[],"oQueAconteceu":["O administrador pediu a desativa\xe7\xe3o de um valor de um fato do cat\xe1logo (`DELETE /api/configuracao/admin/fatos-candidato/{id}/valores/{codigo}`), mas o valor j\xe1 est\xe1 desativado. O valor n\xe3o \xe9 apagado: a desativa\xe7\xe3o s\xf3 impede v\xednculos novos com ele e preserva os que j\xe1 existem (UNI-REQ-0143). Repetir o pedido n\xe3o tem efeito, e a API o recusa em vez de aceit\xe1-lo em sil\xeancio.","As confer\xeancias seguem esta ordem: o fato (`uniplus.configuracao.fato_candidato.nao_encontrado`), a defini\xe7\xe3o do fato de sistema, que \xe9 travada (`uniplus.configuracao.fato_candidato.definicao_do_fato_de_sistema_travada`), o valor (`uniplus.configuracao.fato_valor_dominio.nao_encontrado`) e, por \xfaltimo, o estado do valor. S\xf3 um valor existente de um fato do administrador chega a esta recusa. Nada \xe9 gravado."],"comoResolver":["Nenhuma provid\xeancia \xe9 necess\xe1ria: o valor j\xe1 est\xe1 desativado. Se ele deve voltar a ser oferecido, reative-o (`POST /api/configuracao/admin/fatos-candidato/{id}/valores/{codigo}/ativacao`)."],"ondeAparece":["Desativa\xe7\xe3o de um valor de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato valor dominio"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);